      if(bt<0 || wr<bw || (wr==bw && lr<bl)){bt=t;bw=wr;bl=lr;win=W;} }
    cnt[bt]++; w[win]++; }
  cout<<cnt[0]<<" "<<cnt[1]<<" "<<cnt[2]<<"\n"; for(int i=1;i<=n;i++) cout<<w[i]<<(i<n?" ":"\n"); }

